import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import fullTime from 'flarum/common/helpers/fullTime';
import username from 'flarum/common/helpers/username';
export default class ParticipantFindsModal extends Modal {
  finds = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('scavenger-hunt-finds', {
      filter: {
        hunt: this.attrs.huntId,
        user: this.attrs.user.id()
      },
      include: 'part',
      page: {
        limit: 100
      }
    }).then(finds => {
      this.finds = finds;
      m.redraw();
    });
  }
  className() {
    return 'ParticipantFindsModal Modal--small';
  }
  title() {
    return app.translator.trans('fof-scavenger-hunt.forum.dashboard.participants.finds_title', {
      user: username(this.attrs.user)
    });
  }
  content() {
    if (!this.finds) {
      return m("div", {
        className: "Modal-body"
      }, m(LoadingIndicator, null));
    }
    return m("div", {
      className: "Modal-body"
    }, m("ul", {
      className: "ParticipantFindsModal-list"
    }, this.finds.map(find => {
      const part = find.part();
      return m("li", null, m("strong", null, part ? part.name() : '?'), " \u2014 ", fullTime(find.foundAt()));
    })));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/dashboard/ParticipantFindsModal', ParticipantFindsModal);